package com.bank.semantics.model;

public class EventRecord {
    private final String topic;
    private final int partition;
    private final long sequence; // per-partition sequence for idempotence
    private final String payload;

    public EventRecord(String topic, int partition, long sequence, String payload) {
        this.topic = topic;
        this.partition = partition;
        this.sequence = sequence;
        this.payload = payload;
    }

    public String getTopic() { return topic; }
    public int getPartition() { return partition; }
    public long getSequence() { return sequence; }
    public String getPayload() { return payload; }

    @Override public String toString() { return topic + "#" + partition + " seq=" + sequence + " " + payload; }
}
