package com.bank.semantics.broker;

import com.bank.semantics.model.EventRecord;
import java.util.*;

// Tracks the highest sequence written per (topic,partition) for one producer id.
public class IdempotentBroker {
    private final Map<String, Long> lastSeq = new HashMap<>();
    private final List<EventRecord> log = new ArrayList<>();

    // Returns true if the record was newly written, false if a duplicate retry.
    public boolean append(EventRecord rec) {
        String key = rec.getTopic() + "#" + rec.getPartition();
        long last = lastSeq.getOrDefault(key, -1L);
        if (rec.getSequence() <= last) {
            return false; // duplicate: already written, acknowledge but do not store
        }
        lastSeq.put(key, rec.getSequence());
        log.add(rec);
        return true;
    }

    public List<EventRecord> getLog() { return log; }
}
