package com.bank.semantics.broker;

import com.bank.semantics.model.EventRecord;
import java.util.*;

// Buffers records in an open transaction; only commits make them visible.
// read_committed consumers see getCommittedLog(); aborted records are discarded.
public class TransactionalBroker {
    private final List<EventRecord> committedLog = new ArrayList<>();
    private List<EventRecord> pending = null;

    public void beginTransaction() { pending = new ArrayList<>(); }

    public void send(EventRecord rec) {
        if (pending == null) throw new IllegalStateException("No open transaction");
        pending.add(rec);
    }

    public void commitTransaction() {
        committedLog.addAll(pending);
        pending = null;
    }

    public void abortTransaction() {
        pending = null; // discard everything, nothing becomes visible
    }

    public List<EventRecord> getCommittedLog() { return committedLog; }
}
