package com.bank.semantics;

import com.bank.semantics.broker.IdempotentBroker;
import com.bank.semantics.broker.TransactionalBroker;
import com.bank.semantics.model.EventRecord;
import java.util.logging.*;

public class SemanticsDemo {
    private static final Logger log = Logger.getLogger(SemanticsDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // --- Idempotent producer: retry does not duplicate ---
        IdempotentBroker idem = new IdempotentBroker();
        EventRecord transfer = new EventRecord("transfers", 3, 100,
            "SAV2001->CUR3001 50000");
        boolean first = idem.append(transfer);               // written
        boolean retry = idem.append(transfer);               // ack lost -> retry, deduped
        log.info(() -> "First send stored=" + first + ", retry stored=" + retry
            + ", log size=" + idem.getLog().size());

        // --- Transactional producer: debit+credit atomic, commit ---
        TransactionalBroker tx = new TransactionalBroker();
        tx.beginTransaction();
        tx.send(new EventRecord("accounts", 1, 1, "DEBIT SAV2001 50000"));
        tx.send(new EventRecord("ledger", 2, 1, "CREDIT CUR3001 50000"));
        tx.commitTransaction();
        log.info("After COMMIT, read_committed sees " + tx.getCommittedLog().size() + " records.");

        // --- Transactional producer: crash mid-way -> abort, nothing visible ---
        tx.beginTransaction();
        tx.send(new EventRecord("accounts", 1, 2, "DEBIT SAV2001 99999"));
        log.warning("Crash before credit -> abort transaction");
        tx.abortTransaction();
        log.info("After ABORT, read_committed STILL sees " + tx.getCommittedLog().size()
            + " records (lonely debit never appeared).");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
